entries[41607] = { ["name"] = "Stärkung von Shattrath", ["text"] = "Sofort\nErhöht die maximale Gesundheit des Spielers 1 Stunde lang um 500 und das Ausweichen um 10 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an." }
entries[41608] = { ["name"] = "Unerbittlicher Angriff von Shattrath", ["text"] = "Sofort\nErhöht die Angriffskraft 1 Stunde lang um 120 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
entries[41609] = { ["name"] = "Stärkung von Shattrath", ["text"] = "Sofort\nErhöht 1 Stunde lang die maximale Gesundheit um 500 und das Ausweichen um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
