entries[41911] = { ["name"] = "Legionsring - Zerrütter", ["text"] = "Unbegrenzte Reichweite\nSofort 6 sek. Abklingzeit\nGrüner Blitzstrahl" }
entries[41912] = { ["name"] = "Schattengestalt", ["text"] = "40% von Grundmana\nSofort\nNimmt Schattengestalt an, erhöht verursachten Schattenschaden um 20% und verringert erlittenen Nahkampfschaden um 20%. Die Schattengestalt hält an, bis die Aktion abgebrochen wird." }
entries[41913] = { ["name"] = "Schädlicher Schattengeist Passiv" }
entries[41914] = { ["name"] = "Schädlicher Schattengeist", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht alle 2 Sek. Schattenschaden." }
entries[41915] = { ["name"] = "Schädliche Schattengeister beschwören" }
entries[41916] = { ["name"] = "Legionsring - Schildblitzschlag", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 8 sek.) 6 sek. Abklingzeit\nGrüner Blitzstrahl" }
entries[41917] = { ["name"] = "Schädlicher Schattengeist", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin schädlicher Schattengeist bohrt sich seinen Weg durch das Ziel und fügt ihm 10 Sek. lang alle 2 Sek. 3000 Schattenschaden zu. Wenn der Schattengeist damit fertig ist, lässt er das Ziel hinter sich und sucht sich ein neues Opfer." }
entries[41918] = { ["name"] = "Legionsring - Schildexplosion", ["text"] = "Kanalisiert (Wirken in 1 sek.)" }
entries[41920] = { ["name"] = "Füllen", ["text"] = "5 Meter Reichweite\nWirken in 3 sek.\nFüllt Euren Braufestkrug an einem Festtagsfass des Braufests." }
entries[41921] = { ["name"] = "Gefüllten Braufestkrug benutzen", ["text"] = "Sofort\nEine Probe kristallklaren Gerstenbräus." }
entries[41922] = { ["name"] = "Selbst verlangsamen", ["text"] = "Sofort\nVerlangsamt Supremus und verringert sein Bewegungstempo um 70%." }
entries[41924] = { ["name"] = "Berserker", ["text"] = "Sofort\nErhöht 5 Min. lang das Angriffstempo des Zaubernden um 100% und jeglichen von ihm zugefügten Schaden um 100%." }
